data.variablesTransform:
{
  "msg": [{
    "create":{
      "integrationId": $state.context.REQUEST.DATA.integration.id,
      "modelId": $state.context.REQUEST.DATA.model.id,
      "message": $state.context.REQUEST.DATA.model.name
        & " synchronization failed. An unexpected error occured. See logs for details",
      "typeId": "Failure",
      "data": $state
    }
  },{
  "create": {
    "integrationId": $state.context.REQUEST.DATA.integration.id,
    "message": $state.context.REQUEST.DATA.model.name
        & " synchronization failed. An unexpected error occured. See logs for details",
    "typeId": "Failure",
    "global":true
  }
}]
}

{
  "msg": {
    "create": {
      "integrationId": $state.context.REQUEST.DATA.integration.id,
      "modelId": $state.context.REQUEST.DATA.model.id,
      "message": $state.context.REQUEST.DATA.model.name 
        & " with ID: "
        & $state.context.REQUEST.DATA.id
        & " failed to return results from SuiteQL query",
      "typeId": "Failure"
    }
  }
}

data.transform:

   $state.context.REMOTE.customer.{"createPayload":[$isNilOrEmpty($state.context.LOCAL.customer.id)?{
			"create": {
				"name": $coalesce([entitytitle, entityid]),
				"externalId": $string(id),
				"code": $coalesce([entitytitle, entityid]) & "(" & $string(id)
					& ")",
				"active": isinactive = "F",
				"customerStatusId": isinactive = "F" ? "Active" : "Inactive",
				"integrationData": $
			}
		}],
		"updatePayload":[$isNotNilOrEmpty($state.context.LOCAL.customer.id)?{
			"update": {
        "externalId": $string(id),
				"name": $coalesce([entitytitle, entityid]),
				"code": $coalesce([entitytitle, entityid]) & "(" & $string(id)
					& ")",
				"active": isinactive = "F",
				"customerStatusId": isinactive = "F" ? "Active" : "Inactive",
				"integrationData": $
			},
			"where": { "id": $state.context.LOCAL.customer.id }
		}]}

data.query:
query Query($where: CustomerWhereInput, $orderBy: [CustomerOrderByInput!], $first: Int, $after: String) {
  customer(where: $where, orderBy: $orderBy, first: $first, after: $after) {
  total  
  edges {
      node {
        id
        code
        active
        externalId
        name
        customData
        integrationData
        customerStatusId
      }
    }
  }
}

query Query($where: CustomerAddressWhereInput, $orderBy: [CustomerAddressOrderByInput!], $first: Int, $after: String) {
  customerAddress(where: $where, orderBy: $orderBy, first: $first, after: $after) {
  total  
  edges {
      node {
        id
        code
        active
        billTo
        defaultBilling
        defaultShipping
        dropShip
        remitTo
        shipTo
        addressee
        externalId
        plantIdentifier
        customData
        integrationData
        customerId
      }
    }
  }
}

data.transform:
(
$updates:=$innerJoin( $.customerAddress.edges.node, $state.context.REMOTE.customerAddress, 'externalId', 'nkey', 'joinedKey', { 'grouped': true } );
$inactivate:= $leftAntiJoin( $.customerAddress.edges.node, $state.context.REMOTE.customerAddress, 'externalId', 'nkey');
$new:= $leftAntiJoin( $state.context.REMOTE.customerAddress, $.customerAddress.edges.node, 'nkey', 'externalId');

$sortedData:={
"updateAddress": $updates,
"inactivateAddress": $inactivate ,
"createAddress": $new
};
{
  "createPayload":[ $new.{"create":{
          "externalId": $string(nkey),
          "code": addressee & " (" & $string(nkey) & ")",
          "customerId": $state.context.LOCAL.customer.id,
          "addressee":addressee,
          "address": {
            "lines": [addr1 & "",addr2,addr3],
            "city": city & "",
            "state": state & "",
            "postalCode": zip & "",
            "country": country & ""
          },
          "defaultBilling": defaultbilling='T',
          "defaultShipping": defaultshipping='T',
          "shipTo":defaultshipping='T',
          "remitTo":defaultbilling='T',
          "integrationData": $
        }}],
  "updatePayload": [$updates.{"update": joinedKey.{
          "externalId": $string(nkey),
          "code": addressee & " (" & $string(nkey) & ")",
          "addressee":addressee,
          "customerId": $state.context.LOCAL.customer.id,
          "address": {
            "lines": [addr1 & "",addr2, addr3],
            "city": city & "",
            "state": state & "",
            "postalCode": zip & "",
            "country": country & ""
          },
          "defaultBilling": defaultbilling='T',
          "defaultShipping": defaultshipping='T',
          "shipTo":defaultshipping='T',
          "remitTo":defaultbilling='T',
          "integrationData": $
        },"where": {"id": id}}],
  "inactivatePayload": [$inactivate.{"update": {"active": false},"where": {"id": id}}]
}
)

data.mutation:
mutation Mutation($createPayload: [CustomerAddressCreatePayloadInput!]!, $updatePayload: [CustomerAddressUpdatePayloadInput!]!, $inactivatePayload: [CustomerAddressUpdatePayloadInput!]!) {
  create: createCustomerAddress(payload: $createPayload) {
    id

  }
  update: updateCustomerAddress(payload: $updatePayload) {
    id

  }
  inactivate: updateCustomerAddress(payload: $inactivatePayload) {
    id

  }
}

